using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Tools ---
var tools = new ResearchTools();
var aiTools = new AIFunction[]
{
    AIFunctionFactory.Create(tools.SearchWeb),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

// --- Agent ---
using var loggerFactory = LoggerFactory.Create(b => b
    .AddConsole()
    .SetMinimumLevel(LogLevel.Warning));

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When the user gives you a topic:
        1. Use the SearchWeb tool multiple times with different queries to gather information.
        2. Use SaveNote to record key findings as you go.
        3. Use GetNotes to review everything you collected.
        4. Provide a comprehensive summary with the key points you discovered.
        Be thorough — search at least 3 different angles of the topic.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: aiTools,
    loggerFactory: loggerFactory);

// --- Run ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍 Research Agent Ready        ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or       ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

var session = await agent.CreateSessionAsync();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    tools.ClearNotes();

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"\nResearching \"{input}\"...\n");
    Console.ResetColor();

    try
    {
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        });

        var response = await agent.RunAsync(input, session, runOptions);

        Console.ForegroundColor = ConsoleColor.Green;
        Console.WriteLine("── Summary ─────────────────────────────");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();

        if (tools.NoteCount > 0)
        {
            Console.ForegroundColor = ConsoleColor.Yellow;
            Console.WriteLine($"📝 {tools.NoteCount} note(s) saved during research.");
            Console.ResetColor();
        }

        if (response.Usage is { } usage)
        {
            Console.ForegroundColor = ConsoleColor.DarkGray;
            Console.WriteLine($"Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.Error.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

// ──────────────────────────────────────────────────────────────
//  Tool definitions
// ──────────────────────────────────────────────────────────────

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// Web search uses Bing Search via scraping; notes are kept in memory.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _http = new();

    public int NoteCount => _notes.Count;

    public void ClearNotes() => _notes.Clear();

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🌐 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            using var response = await _http.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync();
            return ParseSearchResults(html);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record important findings.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkMagenta;
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        Console.ResetColor();
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i]}");
        return sb.ToString();
    }

    private static string ParseSearchResults(string html)
    {
        var results = new StringBuilder();
        var count = 0;

        // Extract snippets from DuckDuckGo HTML results
        var snippetMarker = "class=\"result__snippet\"";
        var idx = 0;
        while (count < 5 && (idx = html.IndexOf(snippetMarker, idx, StringComparison.Ordinal)) >= 0)
        {
            idx = html.IndexOf('>', idx) + 1;
            var end = html.IndexOf('<', idx);
            if (end > idx)
            {
                var snippet = System.Net.WebUtility.HtmlDecode(html[idx..end]).Trim();
                if (snippet.Length > 10)
                {
                    count++;
                    results.AppendLine($"• {snippet}");
                }
            }
        }

        // Also extract result titles with links
        var titleMarker = "class=\"result__a\"";
        idx = 0;
        var titleCount = 0;
        while (titleCount < 5 && (idx = html.IndexOf(titleMarker, idx, StringComparison.Ordinal)) >= 0)
        {
            idx = html.IndexOf('>', idx) + 1;
            var end = html.IndexOf('<', idx);
            if (end > idx)
            {
                var title = System.Net.WebUtility.HtmlDecode(html[idx..end]).Trim();
                if (title.Length > 3)
                {
                    titleCount++;
                    results.AppendLine($"  Title: {title}");
                }
            }
        }

        return count > 0
            ? results.ToString()
            : "No results found. Try a different search query.";
    }
}

